#!/bin/bash
SANDBOX="$1"

# `iptables-save` from app-07. It is loaded at boot with iptables-restore.
cat > "$SANDBOX/firewall.rules" <<'EOF'
# Generated by iptables-save v1.8.10 (nf_tables) on Tue Nov 10 08:12:44 2026
*filter
:INPUT DROP [0:0]
:FORWARD DROP [0:0]
:OUTPUT ACCEPT [0:0]
-A INPUT -i lo -j ACCEPT
-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
-A INPUT -p icmp -j ACCEPT
-A INPUT -p tcp -m tcp --dport 80 -j ACCEPT
-A INPUT -p tcp -m tcp --dport 443 -j ACCEPT
-A INPUT -p tcp -m tcp --dport 3306 -j REJECT --reject-with icmp-port-unreachable
-A INPUT -p tcp -m multiport --dports 8000:8999 -m comment --comment "dev ports stay closed" -j DROP
-A INPUT -s 10.20.4.0/24 -p tcp -m tcp --dport 8443 -m comment --comment "admin UI, office only" -j ACCEPT
-A INPUT -s 10.20.0.0/16 -m comment --comment "internal networks" -j ACCEPT
COMMIT
# Completed on Tue Nov 10 08:12:44 2026
EOF

cat > "$SANDBOX/TICKET.txt" <<'EOF'
TICKET-4471  Admin UI unreachable from the office
--------------------------------------------------
The new admin UI on app-07 listens on tcp/8443. We added a firewall rule
so the office network (10.20.4.0/24) can reach it, and reloaded the
firewall from firewall.rules, but connections from the office still time
out. Nobody outside the office may reach 8443, and the rest of the dev
port range (8000-8999) must stay closed, also for the other internal
networks.
EOF
